import {clothMassBrushControls} from './cloth-mass-brush.js';
import {deformableParticleCount} from './deformable-distribution.js';
import {validDeformableDistanceLimits} from './deformable-distance-limits.js';
const keyOf=(r,tether)=>tether?Math.min(r.index,r.anchor)+':'+Math.max(r.index,r.anchor):String(r.index);
export function editClothDistanceRows(p,key,index,anchor,value,action='set'){if(!['motionLimits','distanceTethers','pinWeights'].includes(key)||!['set','remove','clear'].includes(action))throw Error('거리 제약 편집 동작을 확인하세요.');const rows=p[key]||[],tether=key==='distanceTethers',weighted=key==='pinWeights',row=weighted?{index,weight:value}:tether?{index,anchor,distance:value}:{index,radius:value},current=rows.find(r=>keyOf(r,tether)===keyOf(row,tether));if(action!=='clear'&&(!Number.isSafeInteger(index)||index<0||index>=deformableParticleCount(p)||tether&&(!Number.isSafeInteger(anchor)||anchor<0||anchor>=deformableParticleCount(p)||index===anchor)))throw Error('입자 번호 범위를 확인하세요.');if(action==='set'&&current&&(tether?current.distance===value:weighted?current.weight===value:current.radius===value))return rows;const next=action==='clear'?[]:rows.filter(r=>keyOf(r,tether)!==keyOf(row,tether));if(action==='set'&&!(weighted&&value===0))next.push(row);if(!validDeformableDistanceLimits({...p,[key]:next}))throw Error('입자·연결 입자·거리 범위를 확인하세요.');return next;}
export function clothDistanceControls(p,key,attrs,esc,{disabled=false}={}){const count=deformableParticleCount(p),tether=key==='distanceTethers',weighted=key==='pinWeights',rows=p[key]||[],first=rows[0],index=first?.index??0,anchor=first?.anchor??Math.min(1,count-1),value=(weighted?first?.weight:tether?first?.distance:first?.radius)??(weighted ? .5 : 1),off=disabled?' disabled':'';return '<div class="cloth-mass-editor" data-cloth-distance-editor="'+key+'" data-cloth-distance-count="'+count+'"><input type="hidden" '+attrs+' data-cloth-distance-change value="'+esc(JSON.stringify(rows))+'"><div class="component-vector"><label>입자<input type="number" data-cloth-distance-index min="0" max="'+(count-1)+'" step="1" value="'+index+'"'+off+'></label>'+(tether?'<label>연결 입자<input type="number" data-cloth-distance-anchor min="0" max="'+(count-1)+'" step="1" value="'+anchor+'"'+off+'></label>':'')+'<label>'+(weighted?'고정 가중치':tether?'최대 거리 · m':'이동 반경 · m')+'<input type="number" data-cloth-distance-value min="0" max="'+(weighted?1:100000)+'" step=".01" value="'+value+'"'+off+'></label></div><div class="cloth-pin-summary"><span>'+rows.length+' 지정</span><button type="button" data-cloth-distance-action="set"'+off+'>지정</button><button type="button" data-cloth-distance-action="remove"'+off+'>해제</button><button type="button" data-cloth-distance-action="clear"'+off+'>전체 해제</button></div>'+(weighted?clothMassBrushControls(p,attrs,esc,{disabled,pinWeights:true}):'')+'</div>';}
export function handleClothDistanceIndex(event){const input=event.target.closest?.('[data-cloth-distance-index],[data-cloth-distance-anchor]');if(!input||input.disabled)return false;const root=input.closest('[data-cloth-distance-editor]'),tether=root.dataset.clothDistanceEditor==='distanceTethers',index=Number(root.querySelector('[data-cloth-distance-index]').value),anchor=Number(root.querySelector('[data-cloth-distance-anchor]')?.value),rows=JSON.parse(root.querySelector('[data-cloth-distance-change]').value),row=rows.find(r=>keyOf(r,tether)===keyOf({index,anchor},tether));root.querySelector('[data-cloth-distance-value]').value=String((root.dataset.clothDistanceEditor==='pinWeights'?row?.weight:tether?row?.distance:row?.radius)??(root.dataset.clothDistanceEditor==='pinWeights' ? .5 : 1));return true;}
export function handleClothDistanceClick(event){const button=event.target.closest?.('[data-cloth-distance-action]');if(!button||button.disabled)return false;const root=button.closest('[data-cloth-distance-editor]'),key=root.dataset.clothDistanceEditor,count=Number(root.dataset.clothDistanceCount),input=root.querySelector('[data-cloth-distance-change]'),rows=JSON.parse(input.value),index=Number(root.querySelector('[data-cloth-distance-index]').value),anchor=Number(root.querySelector('[data-cloth-distance-anchor]')?.value),value=Number(root.querySelector('[data-cloth-distance-value]').value),next=editClothDistanceRows({particles:count,[key]:rows},key,index,anchor,value,button.dataset.clothDistanceAction);event.preventDefault();event.stopPropagation();if(JSON.stringify(next)!==JSON.stringify(rows)){input.value=JSON.stringify(next);input.dispatchEvent(new input.ownerDocument.defaultView.Event('change',{bubbles:true}));}return true;}
